DROP TABLE IF EXISTS `recorridos_viaje`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `recorridos_viaje` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_viaje` int(11) DEFAULT NULL,
  `movil` varchar(20) NOT NULL,
  `origen` varchar(200) NOT NULL,
  `destino` varchar(200) NOT NULL,
  `origen_lat` decimal(10,8) DEFAULT NULL,
  `origen_lng` decimal(11,8) DEFAULT NULL,
  `destino_lat` decimal(10,8) DEFAULT NULL,
  `destino_lng` decimal(11,8) DEFAULT NULL,
  `distancia` decimal(10,2) DEFAULT NULL COMMENT 'Distancia en km',
  `tiempo` int(11) DEFAULT NULL COMMENT 'Tiempo en minutos',
  `fecha_registro` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_viaje` (`id_viaje`),
  KEY `idx_movil` (`movil`)
) ENGINE=InnoDB AUTO_INCREMENT=137 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

