DROP TABLE IF EXISTS `viajes_despacho`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `viajes_despacho` (
  `id` int(20) NOT NULL AUTO_INCREMENT,
  `cel_pasaj` int(10) NOT NULL,
  `nombre_pasaj` varchar(50) NOT NULL,
  `direccion_origen` varchar(70) NOT NULL,
  `direccion_destino` varchar(70) DEFAULT NULL,
  `puntos_paso` text DEFAULT NULL,
  `obs_operador` varchar(500) NOT NULL,
  `obs_pasaj` varchar(500) NOT NULL,
  `estado` varchar(15) NOT NULL,
  `diferido` varchar(20) NOT NULL,
  `fecha` date DEFAULT NULL,
  `hora` varchar(11) DEFAULT NULL,
  `categoria_movil` varchar(15) NOT NULL,
  `origen_lat` decimal(10,8) DEFAULT NULL,
  `origen_lng` decimal(11,8) DEFAULT NULL,
  `destino_lat` decimal(10,8) DEFAULT NULL,
  `destino_lng` decimal(11,8) DEFAULT NULL,
  `cc` int(4) DEFAULT NULL,
  `centro_de_costo` int(4) DEFAULT NULL,
  `id_autorizante` int(11) DEFAULT NULL,
  `obs_viaje` varchar(255) NOT NULL,
  `id_chofer` int(4) NOT NULL,
  `asignado_a` int(4) DEFAULT 0,
  `fecha_asignacion` datetime DEFAULT NULL,
  `id_cc` int(4) DEFAULT NULL,
  `km_recorridos` decimal(10,2) NOT NULL,
  `peajes` decimal(5,2) NOT NULL,
  `tiempo_espera` int(10) NOT NULL,
  `observaciones_finalizacion` varchar(100) NOT NULL,
  `fecha_finalizacion` date DEFAULT NULL,
  `chofer_nombre_hist` varchar(100) DEFAULT NULL,
  `chofer_apellido_hist` varchar(100) DEFAULT NULL,
  `chofer_celular_hist` varchar(20) DEFAULT NULL,
  `vehiculo_marca_hist` varchar(50) DEFAULT NULL,
  `vehiculo_modelo_hist` varchar(50) DEFAULT NULL,
  `vehiculo_patente_hist` varchar(20) DEFAULT NULL,
  `vehiculo_color_hist` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=243 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

